template:
struct Profile {
    name: String,
    karma: u32,
}

fn main() {
    let profile = Profile {
        name: String::from("crab"),
        karma: 42,
    };
    let display = ⟦expr⟧;
    show(&profile);
    println!("headline: {display}");
}

fn show(p: &Profile) {
    println!("{} has {} karma", p.name, p.karma);
}
